pub fn find_variant_parent(
    type_summaries: Rc<TypeSummaryIndex>,
    variant_name: String,
    scope_enums: Rc<Vec<String>>,
) -> Option<String> {
    if {
        let mut __found = false;
        for en in scope_enums.iter().cloned() {
            if match (*variant_belongs_to_enum(
                type_summaries.clone(),
                variant_name.clone(),
                en.clone(),
            ))
            .clone()
            {
                TypeSummaryQuestion::QuestionNameAmbiguous { leaf: _, .. } => true,
                _ => false,
            } {
                __found = true;
                break;
            }
        }
        __found
    } {
        std::option::Option::None
    } else {
        Rc::new({
            let mut __result = Vec::new();
            for en in scope_enums.iter().cloned() {
                if match (*variant_belongs_to_enum(
                    type_summaries.clone(),
                    variant_name.clone(),
                    en.clone(),
                ))
                .clone()
                {
                    TypeSummaryQuestion::QuestionDecided { value: v, .. } => v.clone(),
                    _ => false,
                } {
                    __result.push(en);
                }
            }
            __result
        })
        .first()
        .cloned()
    }
}

pub fn field_value_shape_from_type_node(type_node: Rc<Node>) -> FieldValueShape {
    {
        let normed = crate::v1_compiler_infer_types::normalize_access_type_node(type_node.clone());
        let is_optional = (normed.return_cardinality.clone() == Cardinality::CardOptional);
        if is_optional.clone() {
            FieldValueShape::OptionalValue
        } else {
            FieldValueShape::PlainValue
        }
    }
}

pub fn is_tuple_type(n: Rc<Node>) -> bool {
    (((n.connective.clone() == Connective::Conj)
        && (n.ident_span.clone() == std::option::Option::None))
        && ((n.children.clone().len() as i64) == 2))
}

pub fn build_struct_field_summaries(
    parent: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<HashMap<String, Rc<FieldSummary>>> {
    {
        let is_pair = is_tuple_type(parent.clone());
        Rc::new(
            parent
                .children
                .clone()
                .iter()
                .cloned()
                .enumerate()
                .map(|(i, v)| (i as i64, v))
                .collect::<Vec<_>>(),
        )
        .iter()
        .cloned()
        .fold(
            v1_rt::rc_empty_map::<String, Rc<FieldSummary>>(),
            |acc: Rc<HashMap<String, Rc<FieldSummary>>>, pair: (i64, Rc<Node>)| {
                let idx = pair.0.clone();
                let child = pair.1.clone();
                if (child.inferred.clone() == std::option::Option::None) {
                    acc.clone()
                } else {
                    {
                        let style = if is_pair.clone() {
                            if (idx.clone() == 0) {
                                FieldAccessStyle::TupleFirst
                            } else {
                                FieldAccessStyle::TupleSecond
                            }
                        } else {
                            FieldAccessStyle::StoredField
                        };
                        let key = crate::v1_std_core::authored_name_at(
                            source_indices.clone(),
                            child.clone(),
                        );
                        v1_rt::rc_map_insert(
                            acc.clone(),
                            key.clone(),
                            Rc::new(FieldSummary {
                                access_style: style.clone(),
                                value_shape: field_value_shape_from_type_node(
                                    crate::v1_compiler_infer_types::child_type_node(child.clone()),
                                ),
                            }),
                        )
                    }
                }
            },
        )
    }
}

pub fn find_first_enum_field_node(
    variants: Rc<Vec<Rc<Node>>>,
    field_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<Rc<Node>> {
    match variants.clone().first().cloned() {
        Some(variant) => match crate::v1_std_core::find_child_named(
            variant.clone(),
            field_name.clone(),
            source_indices.clone(),
        ) {
            Some(field_child) => Some(field_child.clone()),
            std::option::Option::None => std::option::Option::None,
        },
        std::option::Option::None => std::option::Option::None,
    }
}

pub fn enum_field_present_in_all_variants(
    variants: Rc<Vec<Rc<Node>>>,
    field_name: String,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let mut __all = true;
        for variant in variants.iter().cloned() {
            if !(crate::v1_std_core::has_child_named(
                variant.clone(),
                field_name.clone(),
                source_indices.clone(),
            )) {
                __all = false;
                break;
            }
        }
        __all
    }
}

pub fn enum_field_type_consistent(
    variants: Rc<Vec<Rc<Node>>>,
    field_name: String,
    expected: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let mut __all = true;
        for variant in variants.iter().cloned() {
            if !(match crate::v1_std_core::find_child_named(
                variant.clone(),
                field_name.clone(),
                source_indices.clone(),
            ) {
                Some(field_child) => crate::v1_compiler_infer_types::node_type_equals(
                    crate::v1_compiler_infer_types::child_type_node(field_child.clone()),
                    expected.clone(),
                    source_indices.clone(),
                    Rc::new(TextJudgment::TextNotAsked {
                        reason: TextNotAskedReason::TextNotAskedInVariantFieldSummary,
                    }),
                ),
                std::option::Option::None => false,
            }) {
                __all = false;
                break;
            }
        }
        __all
    }
}

pub fn build_enum_field_summaries(
    variants: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<HashMap<String, Rc<FieldSummary>>> {
    {
        let first_field_names = match variants.clone().first().cloned() {
            Some(first_variant) => Rc::new({
                let mut __result = Vec::new();
                for f in first_variant.children.clone().iter().cloned() {
                    __result.push(crate::v1_std_core::authored_name_at(
                        source_indices.clone(),
                        f.clone(),
                    ));
                }
                __result
            }),
            std::option::Option::None => Rc::new(vec![]),
        };
        let shared = Rc::new({
            let mut __result = Vec::new();
            for field_name in first_field_names.iter().cloned() {
                if enum_field_present_in_all_variants(
                    variants.clone(),
                    field_name.clone(),
                    source_indices.clone(),
                ) {
                    __result.push(field_name);
                }
            }
            __result
        });
        let consistent = Rc::new({
            let mut __result = Vec::new();
            for field_name in shared.iter().cloned() {
                if match find_first_enum_field_node(
                    variants.clone(),
                    field_name.clone(),
                    source_indices.clone(),
                ) {
                    Some(first_field) => enum_field_type_consistent(
                        variants.clone(),
                        field_name.clone(),
                        crate::v1_compiler_infer_types::child_type_node(first_field.clone()),
                        source_indices.clone(),
                    ),
                    std::option::Option::None => false,
                } {
                    __result.push(field_name);
                }
            }
            __result
        });
        consistent.iter().cloned().fold(
            v1_rt::rc_empty_map::<String, Rc<FieldSummary>>(),
            |acc: Rc<HashMap<String, Rc<FieldSummary>>>, field_name: String| {
                match find_first_enum_field_node(
                    variants.clone(),
                    field_name.clone(),
                    source_indices.clone(),
                ) {
                    Some(first_field) => v1_rt::rc_map_insert(
                        acc.clone(),
                        field_name.clone(),
                        Rc::new(FieldSummary {
                            access_style: FieldAccessStyle::EnumAccessor,
                            value_shape: field_value_shape_from_type_node(
                                crate::v1_compiler_infer_types::child_type_node(
                                    first_field.clone(),
                                ),
                            ),
                        }),
                    ),
                    std::option::Option::None => acc.clone(),
                }
            },
        )
    }
}

pub fn build_field_type_map(
    children: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<FieldTypeMapBuild> {
    children.iter().cloned().fold(
        Rc::new(FieldTypeMapBuild {
            field_types: v1_rt::rc_empty_map::<String, String>(),
            import_surface_names: Rc::new(vec![]),
        }),
        |acc: Rc<FieldTypeMapBuild>, child: Rc<Node>| match child
            .inferred
            .clone()
            .as_deref()
            .cloned()
        {
            Some(InferredNode::Resolved { node: ft, .. }) => {
                let resolved_name = crate::v1_std_core::authored_name_at(
                    source_indices.clone(),
                    crate::v1_compiler_infer_types::normalize_access_type_node(ft.clone()),
                );
                let ft_is_type_var = if (ft.inferred.clone() != std::option::Option::None) {
                    is_type_variable(ft.inferred.clone().clone().unwrap())
                } else {
                    false
                };
                let key =
                    crate::v1_std_core::authored_name_at(source_indices.clone(), child.clone());
                let surface_names =
                    collect_type_node_import_surface_names(ft.clone(), source_indices.clone());
                let next_field_types = if (((resolved_name.clone() != "".to_string())
                    && !ft_is_type_var.clone())
                    && (resolved_name.clone() != "Dynamic".to_string()))
                {
                    v1_rt::rc_map_insert(
                        acc.field_types.clone(),
                        key.clone(),
                        resolved_name.clone(),
                    )
                } else {
                    acc.field_types.clone()
                };
                Rc::new(FieldTypeMapBuild {
                    field_types: next_field_types.clone(),
                    import_surface_names: dedupe_nonempty_strings(v1_rt::concat(
                        acc.import_surface_names.clone(),
                        surface_names.clone(),
                    )),
                })
            }
            _ => acc.clone(),
        },
    )
}

pub fn build_type_summary(
    item: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Option<Rc<TypeSummary>> {
    {
        if (((item.connective.clone() == Connective::NoConnective)
            || (item.connective.clone() == Connective::Arrow))
            || (item.transport.clone() != std::option::Option::None))
        {
            return std::option::Option::None;
        }
        let gpn = Rc::new({
            let mut __result = Vec::new();
            for p in item.params.clone().iter().cloned() {
                __result.push(crate::v1_std_core::param_node_name_at(
                    p.clone(),
                    source_indices.clone(),
                ));
            }
            __result
        });
        let is_product = (item.connective.clone() == Connective::Conj);
        let has_fn = {
            let mut __found = false;
            for child in item.children.clone().iter().cloned() {
                if match child.inferred.clone().as_deref().cloned() {
                    Some(InferredNode::Resolved { node: rt, .. }) => {
                        (rt.connective.clone() == Connective::Arrow)
                    }
                    _ => false,
                } {
                    __found = true;
                    break;
                }
            }
            __found
        };
        if is_product.clone() {
            {
                let field_types =
                    build_field_type_map(item.children.clone(), source_indices.clone());
                Some(Rc::new(TypeSummary {
                    name: crate::v1_std_core::authored_name_at(
                        source_indices.clone(),
                        item.clone(),
                    ),
                    key: "".to_string(),
                    repr: Rc::new(TypeRepr::StructRepr),
                    field_summaries: build_struct_field_summaries(
                        item.clone(),
                        source_indices.clone(),
                    ),
                    field_type_map: field_types.field_types.clone(),
                    field_import_surface_names: field_types.import_surface_names.clone(),
                    variant_name_set: v1_rt::rc_empty_map::<String, bool>(),
                    generic_param_names: gpn.clone(),
                    has_fn_fields: has_fn.clone(),
                }))
            }
        } else {
            {
                let unit_only = {
                    let mut __all = true;
                    for child in item.children.clone().iter().cloned() {
                        if !((child.children.clone().len() as i64) == 0) {
                            __all = false;
                            break;
                        }
                    }
                    __all
                };
                Some(Rc::new(TypeSummary {
                    name: crate::v1_std_core::authored_name_at(
                        source_indices.clone(),
                        item.clone(),
                    ),
                    key: "".to_string(),
                    repr: Rc::new(TypeRepr::EnumRepr {
                        unit_only: unit_only.clone(),
                    }),
                    field_summaries: build_enum_field_summaries(
                        item.children.clone(),
                        source_indices.clone(),
                    ),
                    field_type_map: v1_rt::rc_empty_map::<String, String>(),
                    field_import_surface_names: enum_variant_payload_surface_names(
                        item.children.clone(),
                        source_indices.clone(),
                    ),
                    variant_name_set: item.children.clone().iter().cloned().fold(
                        v1_rt::rc_empty_map::<String, bool>(),
                        |acc: Rc<HashMap<String, bool>>, child: Rc<Node>| {
                            v1_rt::rc_map_insert(
                                acc,
                                crate::v1_std_core::authored_name_at(
                                    source_indices.clone(),
                                    child.clone(),
                                ),
                                true,
                            )
                        },
                    ),
                    generic_param_names: gpn.clone(),
                    has_fn_fields: (has_fn.clone()
                        || enum_variant_payload_has_fn(item.children.clone())),
                }))
            }
        }
    }
}

pub fn enum_variant_payload_surface_names(
    variants: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<Vec<String>> {
    dedupe_nonempty_strings(Rc::new({
        let mut __result = Vec::new();
        for v in variants.iter().cloned() {
            __result.extend(
                (*{
                    let built = build_field_type_map(v.children.clone(), source_indices.clone());
                    built.import_surface_names.clone()
                })
                .iter()
                .cloned(),
            );
        }
        __result
    }))
}

pub fn enum_variant_payload_has_fn(variants: Rc<Vec<Rc<Node>>>) -> bool {
    {
        let mut __found = false;
        for v in variants.iter().cloned() {
            if {
                let mut __found = false;
                for child in v.children.clone().iter().cloned() {
                    if match child.inferred.clone().as_deref().cloned() {
                        Some(InferredNode::Resolved { node: rt, .. }) => {
                            (rt.connective.clone() == Connective::Arrow)
                        }
                        _ => false,
                    } {
                        __found = true;
                        break;
                    }
                }
                __found
            } {
                __found = true;
                break;
            }
        }
        __found
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct FnReachRound {
    pub reached: Rc<BTreeSet<String>>,
    pub grew: bool,
}

pub fn fn_reach_target_keys(index: Rc<TypeSummaryIndex>, target: String) -> Rc<Vec<String>> {
    match v1_rt::map_get(&index.by_key.clone(), target.clone()) {
        Some(_) => Rc::new(vec![target.clone()]),
        std::option::Option::None => v1_rt::concat(
            type_summary_keys_of_leaf(index.clone(), target.clone()),
            Rc::new(vec![target.clone()]),
        ),
    }
}

pub fn fn_reach_holds_directly(
    name: String,
    summaries: Rc<TypeSummaryIndex>,
    structural_alias_direct_fn_names: Rc<BTreeSet<String>>,
) -> bool {
    match v1_rt::map_get(&summaries.by_key.clone(), name.clone()) {
        Some(s) => s.has_fn_fields.clone(),
        std::option::Option::None => {
            v1_rt::set_contains(&structural_alias_direct_fn_names, name.clone())
        }
    }
}

pub fn fn_reach_targets(
    name: String,
    summaries: Rc<TypeSummaryIndex>,
    structural_alias_fn_surface_names: Rc<HashMap<String, Rc<Vec<String>>>>,
) -> Rc<Vec<String>> {
    {
        let spelled = match v1_rt::map_get(&summaries.by_key.clone(), name.clone()) {
            Some(s) => v1_rt::concat(
                Rc::new(v1_rt::map_values(&s.field_type_map.clone())),
                s.field_import_surface_names.clone(),
            ),
            std::option::Option::None => {
                match v1_rt::map_get(&structural_alias_fn_surface_names, name.clone()) {
                    Some(targets) => targets.clone(),
                    std::option::Option::None => Rc::new(vec![]),
                }
            }
        };
        spelled
            .iter()
            .cloned()
            .fold(Rc::new(vec![]), |acc: Rc<Vec<String>>, t: String| {
                v1_rt::concat(acc, fn_reach_target_keys(summaries.clone(), t.clone()))
            })
    }
}

pub fn fn_reaching_names_fixpoint(
    mut __tco_loop_candidates: Rc<Vec<String>>,
    mut __tco_loop_summaries: Rc<TypeSummaryIndex>,
    mut __tco_loop_structural_alias_fn_surface_names: Rc<HashMap<String, Rc<Vec<String>>>>,
    mut __tco_loop_structural_alias_direct_fn_names: Rc<BTreeSet<String>>,
    mut __tco_loop_reached: Rc<BTreeSet<String>>,
) -> Rc<BTreeSet<String>> {
    loop {
        #[allow(unused_mut)]
        let mut candidates = __tco_loop_candidates;
        #[allow(unused_mut)]
        let mut summaries = __tco_loop_summaries;
        #[allow(unused_mut)]
        let mut structural_alias_fn_surface_names = __tco_loop_structural_alias_fn_surface_names;
        #[allow(unused_mut)]
        let mut structural_alias_direct_fn_names = __tco_loop_structural_alias_direct_fn_names;
        #[allow(unused_mut)]
        let mut reached = __tco_loop_reached;
        let round = candidates.iter().cloned().fold(
            Rc::new(FnReachRound {
                reached: reached.clone(),
                grew: false,
            }),
            |acc: Rc<FnReachRound>, name: String| {
                if v1_rt::set_contains(&acc.reached.clone(), name.clone()) {
                    acc.clone()
                } else {
                    if (fn_reach_holds_directly(
                        name.clone(),
                        summaries.clone(),
                        structural_alias_direct_fn_names.clone(),
                    ) || {
                        let mut __found = false;
                        for target in fn_reach_targets(
                            name.clone(),
                            summaries.clone(),
                            structural_alias_fn_surface_names.clone(),
                        )
                        .iter()
                        .cloned()
                        {
                            if (v1_rt::set_contains(&acc.reached.clone(), target.clone())
                                || fn_reach_holds_directly(
                                    target.clone(),
                                    summaries.clone(),
                                    structural_alias_direct_fn_names.clone(),
                                ))
                            {
                                __found = true;
                                break;
                            }
                        }
                        __found
                    }) {
                        Rc::new(FnReachRound {
                            reached: v1_rt::rc_set_insert(acc.reached.clone(), name.clone()),
                            grew: true,
                        })
                    } else {
                        acc.clone()
                    }
                }
            },
        );
        if round.grew.clone() {
            {
                let __tco_0 = candidates;
                let __tco_1 = summaries;
                let __tco_2 = structural_alias_fn_surface_names;
                let __tco_3 = structural_alias_direct_fn_names;
                let __tco_4 = round.reached.clone();
                __tco_loop_candidates = __tco_0;
                __tco_loop_summaries = __tco_1;
                __tco_loop_structural_alias_fn_surface_names = __tco_2;
                __tco_loop_structural_alias_direct_fn_names = __tco_3;
                __tco_loop_reached = __tco_4;
                continue;
            }
        } else {
            break round.reached.clone();
        }
    }
}

pub fn fn_reaching_names(
    summaries: Rc<TypeSummaryIndex>,
    structural_alias_fn_surface_names: Rc<HashMap<String, Rc<Vec<String>>>>,
    structural_alias_direct_fn_names: Rc<BTreeSet<String>>,
) -> Rc<BTreeSet<String>> {
    fn_reaching_names_fixpoint(
        v1_rt::concat(
            Rc::new(v1_rt::map_keys(&summaries.by_key.clone())),
            Rc::new(v1_rt::map_keys(&structural_alias_fn_surface_names)),
        ),
        summaries.clone(),
        structural_alias_fn_surface_names.clone(),
        structural_alias_direct_fn_names.clone(),
        v1_rt::rc_empty_set::<String>(),
    )
}

pub fn close_fn_fields(
    summaries: Rc<TypeSummaryIndex>,
    structural_alias_fn_surface_names: Rc<HashMap<String, Rc<Vec<String>>>>,
    structural_alias_direct_fn_names: Rc<BTreeSet<String>>,
) -> Rc<TypeSummaryIndex> {
    {
        let reaching = fn_reaching_names(
            summaries.clone(),
            structural_alias_fn_surface_names.clone(),
            structural_alias_direct_fn_names.clone(),
        );
        Rc::new(TypeSummaryIndex {
            by_key: Rc::new(v1_rt::map_keys(&summaries.by_key.clone()))
                .iter()
                .cloned()
                .fold(
                    summaries.by_key.clone(),
                    |acc: Rc<HashMap<String, Rc<TypeSummary>>>, key: String| match v1_rt::map_get(
                        &summaries.by_key.clone(),
                        key.clone(),
                    ) {
                        Some(s) => {
                            if (!s.has_fn_fields.clone()
                                && v1_rt::set_contains(&reaching, key.clone()))
                            {
                                v1_rt::rc_map_insert(
                                    acc.clone(),
                                    key.clone(),
                                    Rc::new(TypeSummary {
                                        name: s.name.clone(),
                                        key: s.key.clone(),
                                        repr: s.repr.clone(),
                                        field_summaries: s.field_summaries.clone(),
                                        field_type_map: s.field_type_map.clone(),
                                        field_import_surface_names: s
                                            .field_import_surface_names
                                            .clone(),
                                        variant_name_set: s.variant_name_set.clone(),
                                        generic_param_names: s.generic_param_names.clone(),
                                        has_fn_fields: true,
                                    }),
                                )
                            } else {
                                acc.clone()
                            }
                        }
                        std::option::Option::None => acc.clone(),
                    },
                ),
            keys_by_leaf: summaries.keys_by_leaf.clone(),
        })
    }
}

pub fn structural_alias_direct_fn_names_with(
    names: Rc<BTreeSet<String>>,
    name: String,
    include: bool,
) -> Rc<BTreeSet<String>> {
    if include.clone() {
        v1_rt::rc_set_insert(names.clone(), name.clone())
    } else {
        names.clone()
    }
}

pub fn add_emit_item_summary(
    state: Rc<EmitInfoBuildState>,
    module_name: String,
    item: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> Rc<EmitInfoBuildState> {
    {
        let decl_name = crate::v1_std_core::authored_name_at(source_indices.clone(), item.clone());
        let alias_rhs = crate::v1_compiler_infer_types::resolved_type(item.clone());
        let alias_rhs_name =
            crate::v1_std_core::authored_name_at(source_indices.clone(), alias_rhs.clone());
        let is_type_alias = (((((((decl_name.clone() != "".to_string())
            && (item.connective.clone() == Connective::NoConnective))
            && (item.body.clone() == std::option::Option::None))
            && ((item.params.clone().len() as i64) == 0))
            && (item.transport.clone() == std::option::Option::None))
            && ((item.children.clone().len() as i64) == 0))
            && (alias_rhs_name.clone() != "Unit".to_string()));
        let is_structural_alias = if is_type_alias.clone() {
            match crate::v1_compiler_coercion::realized_checkpoint(
                crate::v1_compiler_coercion::declaration_realization(
                    item.clone(),
                    decl_name.clone(),
                    RenderTarget::Rust,
                ),
            ) {
                Some(_) => false,
                std::option::Option::None => true,
            }
        } else {
            false
        };
        let structural_alias_fn_surface_names = if is_structural_alias.clone() {
            v1_rt::rc_map_insert(
                state.structural_alias_fn_surface_names.clone(),
                decl_name.clone(),
                collect_type_node_import_surface_names(alias_rhs.clone(), source_indices.clone()),
            )
        } else {
            state.structural_alias_fn_surface_names.clone()
        };
        let prior_direct_fn_names = state.structural_alias_direct_fn_names.clone();
        let structural_alias_direct_fn_names = structural_alias_direct_fn_names_with(
            prior_direct_fn_names.clone(),
            decl_name.clone(),
            (is_structural_alias.clone() && (alias_rhs.connective.clone() == Connective::Arrow)),
        );
        let state = if ((decl_name.clone() != "".to_string())
            && emit_graph_records_type_decl(item.clone(), source_indices.clone()))
        {
            Rc::new(EmitInfoBuildState {
                type_summaries: state.type_summaries.clone(),
                type_decl_items: type_decl_index_insert(
                    state.type_decl_items.clone(),
                    module_name.clone(),
                    decl_name.clone(),
                    item.clone(),
                ),
                fn_decl_items: state.fn_decl_items.clone(),
                structural_alias_fn_surface_names: structural_alias_fn_surface_names.clone(),
                structural_alias_direct_fn_names: structural_alias_direct_fn_names.clone(),
            })
        } else {
            state.clone()
        };
        let state = if ((decl_name.clone() != "".to_string())
            && emit_graph_records_fn_decl(item.clone()))
        {
            Rc::new(EmitInfoBuildState {
                type_summaries: state.type_summaries.clone(),
                type_decl_items: state.type_decl_items.clone(),
                fn_decl_items: v1_rt::rc_map_insert(
                    state.fn_decl_items.clone(),
                    decl_name.clone(),
                    item.clone(),
                ),
                structural_alias_fn_surface_names: state.structural_alias_fn_surface_names.clone(),
                structural_alias_direct_fn_names: state.structural_alias_direct_fn_names.clone(),
            })
        } else {
            state.clone()
        };
        match build_type_summary(item.clone(), source_indices.clone()) {
            Some(built) => {
                let key = type_decl_identity(module_name.clone(), built.name.clone());
                let summary = type_summary_with_key(built.clone(), key.clone());
                let with_variants =
                    match (*summary.repr.clone()).clone() {
                        TypeRepr::EnumRepr { unit_only: _, .. } => {
                            item.children.clone().iter().cloned().fold(
                                state.type_summaries.clone(),
                                |acc: Rc<TypeSummaryIndex>, variant: Rc<Node>| {
                                    if ((variant.children.clone().len() as i64) > 0) {
                                        {
                                            let v_has_fn = {
                                                let mut __found = false;
                                                for vc in variant.children.clone().iter().cloned() {
                                                    if match vc.inferred.clone().as_deref().cloned()
                                                    {
                                                        Some(InferredNode::Resolved {
                                                            node: rt,
                                                            ..
                                                        }) => {
                                                            (rt.connective.clone()
                                                                == Connective::Arrow)
                                                        }
                                                        _ => false,
                                                    } {
                                                        __found = true;
                                                        break;
                                                    }
                                                }
                                                __found
                                            };
                                            let vname = crate::v1_std_core::authored_name_at(
                                                source_indices.clone(),
                                                variant.clone(),
                                            );
                                            let qualified_vname = variant_summary_key(
                                                summary.name.clone(),
                                                vname.clone(),
                                            );
                                            let variant_key =
                                                variant_summary_key(key.clone(), vname.clone());
                                            let variant_field_types = build_field_type_map(
                                                variant.children.clone(),
                                                source_indices.clone(),
                                            );
                                            type_summary_index_insert(
                                                acc.clone(),
                                                variant_key.clone(),
                                                qualified_vname.clone(),
                                                Rc::new(TypeSummary {
                                                    name: qualified_vname.clone(),
                                                    key: variant_key.clone(),
                                                    repr: Rc::new(TypeRepr::StructRepr),
                                                    field_summaries: build_struct_field_summaries(
                                                        variant.clone(),
                                                        source_indices.clone(),
                                                    ),
                                                    field_type_map: variant_field_types
                                                        .field_types
                                                        .clone(),
                                                    field_import_surface_names: variant_field_types
                                                        .import_surface_names
                                                        .clone(),
                                                    variant_name_set: v1_rt::rc_empty_map::<
                                                        String,
                                                        bool,
                                                    >(
                                                    ),
                                                    generic_param_names: Rc::new(vec![]),
                                                    has_fn_fields: v_has_fn.clone(),
                                                }),
                                            )
                                        }
                                    } else {
                                        acc.clone()
                                    }
                                },
                            )
                        }
                        _ => state.type_summaries.clone(),
                    };
                let next_summaries = type_summary_index_insert(
                    with_variants.clone(),
                    key.clone(),
                    summary.name.clone(),
                    summary.clone(),
                );
                Rc::new(EmitInfoBuildState {
                    type_summaries: next_summaries.clone(),
                    type_decl_items: state.type_decl_items.clone(),
                    fn_decl_items: state.fn_decl_items.clone(),
                    structural_alias_fn_surface_names: state
                        .structural_alias_fn_surface_names
                        .clone(),
                    structural_alias_direct_fn_names: state
                        .structural_alias_direct_fn_names
                        .clone(),
                })
            }
            std::option::Option::None => state.clone(),
        }
    }
}

pub fn type_summary_with_key(summary: Rc<TypeSummary>, key: String) -> Rc<TypeSummary> {
    Rc::new(TypeSummary {
        name: summary.name.clone(),
        key: key.clone(),
        repr: summary.repr.clone(),
        field_summaries: summary.field_summaries.clone(),
        field_type_map: summary.field_type_map.clone(),
        field_import_surface_names: summary.field_import_surface_names.clone(),
        variant_name_set: summary.variant_name_set.clone(),
        generic_param_names: summary.generic_param_names.clone(),
        has_fn_fields: summary.has_fn_fields.clone(),
    })
}

pub fn emit_dependency_registration_dissolve_on_note() -> Rc<DissolutionCondition> {
    thread_local! {
        static CACHED: Rc<DissolutionCondition> = {
            crate::std_dissolution::unbound_dissolution("dissolve-on (FreeMonoid pass 2026-07-20): collect emitted cross-module type/path refs during emit into one authority; derive (a) use-lines via build_shared_types + reference_derived_use_line_plan and (b) closure pub-mod membership via emit_lib_rs_from_paths from that set. Instance-patch interim: closure projections (v1.compiler.closure_stub_v2_std_text_rust and closure_stub_v2_std_integer_rust) when refs exist but the real v2.std.text or v2.std.integer module is absent from narrow typed.modules — projections are NOT parallel modeling authorities (see each stub module dissolve_on_note); they dissolve when the ref set includes the real module in the closure.".to_string())
        };
    }
    CACHED.with(|c: &Rc<DissolutionCondition>| c.clone())
}

